class Solution {
public:
    vector<string> fizzBuzz(int n) {
        vector<string> answer;
        for (int i = 1; i <= n; ++i) {
            if (i % 15 == 0) answer.push_back("FizzBuzz");
            else if (i % 3 == 0) answer.push_back("Fizz");
            else if (i % 5 == 0) answer.push_back("Buzz");
            else answer.push_back(to_string(i));
        }
        return answer;
    }
};

class Solution {
public:
    int numberOfSteps(int num) {
        int steps = 0;
        while (num) {
            num = (num % 2 == 0) ? num / 2 : num - 1;
            ++steps;
        }
        return steps;
    }
};

class Solution {
public:
    int subtractProductAndSum(int n) {
        int product = 1, sum = 0;
        while (n) {
            int digit = n % 10;
            product *= digit;
            sum += digit;
            n /= 10;
        }
        return product - sum;
    }
};

class Solution {
public:
    bool isPalindrome(int x) {
        if (x < 0) return false;
        long long reversed = 0, value = x;
        while (value) {
            reversed = reversed * 10 + value % 10;
            value /= 10;
        }
        return reversed == x;
    }
};

class Solution {
public:
    bool isPowerOfTwo(int n) {
        return n > 0 && (n & (n - 1)) == 0;
    }
};

class Solution {
public:
    vector<int> buildArray(vector<int>& nums) {
        vector<int> answer(nums.size());
        for (int i = 0; i < nums.size(); ++i) answer[i] = nums[nums[i]];
        return answer;
    }
};

class Solution {
public:
    vector<int> runningSum(vector<int>& nums) {
        for (int i = 1; i < nums.size(); ++i) nums[i] += nums[i - 1];
        return nums;
    }
};

class Solution {
public:
    int findNumbers(vector<int>& nums) {
        int answer = 0;
        for (int value : nums) {
            int digits = 0;
            do { ++digits; value /= 10; } while (value);
            answer += digits % 2 == 0;
        }
        return answer;
    }
};

class Solution {
public:
    int maximumWealth(vector<vector<int>>& accounts) {
        int best = 0;
        for (const auto& customer : accounts)
            best = max(best, accumulate(customer.begin(), customer.end(), 0));
        return best;
    }
};

class Solution {
public:
    int findMaxConsecutiveOnes(vector<int>& nums) {
        int current = 0, best = 0;
        for (int value : nums) {
            current = value == 1 ? current + 1 : 0;
            best = max(best, current);
        }
        return best;
    }
};

class Solution {
public:
    int largestAltitude(vector<int>& gain) {
        int altitude = 0, highest = 0;
        for (int change : gain) {
            altitude += change;
            highest = max(highest, altitude);
        }
        return highest;
    }
};

class Solution {
public:
    int removeElement(vector<int>& nums, int val) {
        int write = 0;
        for (int value : nums) if (value != val) nums[write++] = value;
        return write;
    }
};

class Solution {
public:
    int removeDuplicates(vector<int>& nums) {
        if (nums.empty()) return 0;
        int write = 1;
        for (int read = 1; read < nums.size(); ++read)
            if (nums[read] != nums[write - 1]) nums[write++] = nums[read];
        return write;
    }
};

class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        int write = 0;
        for (int value : nums) if (value != 0) nums[write++] = value;
        while (write < nums.size()) nums[write++] = 0;
    }
};

class Solution {
public:
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        int i = m - 1, j = n - 1, write = m + n - 1;
        while (j >= 0) {
            if (i >= 0 && nums1[i] > nums2[j]) nums1[write--] = nums1[i--];
            else nums1[write--] = nums2[j--];
        }
    }
};

class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int answer = nums.size();
        for (int i = 0; i < nums.size(); ++i) answer ^= i ^ nums[i];
        return answer;
    }
};

class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int answer = 0;
        for (int value : nums) answer ^= value;
        return answer;
    }
};

class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int minimum = INT_MAX, profit = 0;
        for (int price : prices) {
            minimum = min(minimum, price);
            profit = max(profit, price - minimum);
        }
        return profit;
    }
};

class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        k %= nums.size();
        reverse(nums.begin(), nums.end());
        reverse(nums.begin(), nums.begin() + k);
        reverse(nums.begin() + k, nums.end());
    }
};

class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        vector<int> answer(nums.size(), 1);
        int prefix = 1, suffix = 1;
        for (int i = 0; i < nums.size(); ++i) {
            answer[i] = prefix;
            prefix *= nums[i];
        }
        for (int i = nums.size() - 1; i >= 0; --i) {
            answer[i] *= suffix;
            suffix *= nums[i];
        }
        return answer;
    }
};

class Solution {
public:
    void reverseString(vector<char>& s) {
        int left = 0, right = s.size() - 1;
        while (left < right) swap(s[left++], s[right--]);
    }
};

class Solution {
public:
    bool isPalindrome(string s) {
        int left = 0, right = s.size() - 1;
        while (left < right) {
            while (left < right && !isalnum((unsigned char)s[left])) ++left;
            while (left < right && !isalnum((unsigned char)s[right])) --right;
            if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right])) return false;
            ++left; --right;
        }
        return true;
    }
};

class Solution {
public:
    int firstUniqChar(string s) {
        array<int, 26> count{};
        for (char c : s) ++count[c - 'a'];
        for (int i = 0; i < s.size(); ++i) if (count[s[i] - 'a'] == 1) return i;
        return -1;
    }
};

class Solution {
public:
    string longestCommonPrefix(vector<string>& strs) {
        string prefix = strs[0];
        for (int i = 1; i < strs.size(); ++i)
            while (strs[i].find(prefix) != 0) prefix.pop_back();
        return prefix;
    }
};

class Solution {
public:
    bool isAnagram(string s, string t) {
        if (s.size() != t.size()) return false;
        array<int, 26> count{};
        for (char c : s) ++count[c - 'a'];
        for (char c : t) --count[c - 'a'];
        return all_of(count.begin(), count.end(), [](int x) { return x == 0; });
    }
};

class Solution {
public:
    bool containsDuplicate(vector<int>& nums) {
        unordered_set<int> seen;
        for (int value : nums) if (!seen.insert(value).second) return true;
        return false;
    }
};

class Solution {
public:
    bool containsNearbyDuplicate(vector<int>& nums, int k) {
        unordered_map<int, int> last;
        for (int i = 0; i < nums.size(); ++i) {
            if (last.count(nums[i]) && i - last[nums[i]] <= k) return true;
            last[nums[i]] = i;
        }
        return false;
    }
};

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> index;
        for (int i = 0; i < nums.size(); ++i) {
            int need = target - nums[i];
            if (index.count(need)) return {index[need], i};
            index[nums[i]] = i;
        }
        return {};
    }
};

class Solution {
public:
    int majorityElement(vector<int>& nums) {
        int candidate = 0, votes = 0;
        for (int value : nums) {
            if (votes == 0) candidate = value;
            votes += value == candidate ? 1 : -1;
        }
        return candidate;
    }
};

class Solution {
public:
    vector<int> intersection(vector<int>& nums1, vector<int>& nums2) {
        unordered_set<int> first(nums1.begin(), nums1.end()), common;
        for (int value : nums2) if (first.count(value)) common.insert(value);
        return vector<int>(common.begin(), common.end());
    }
};

class Solution {
    int next(int n) {
        int sum = 0;
        while (n) { int d = n % 10; sum += d * d; n /= 10; }
        return sum;
    }
public:
    bool isHappy(int n) {
        unordered_set<int> seen;
        while (n != 1 && seen.insert(n).second) n = next(n);
        return n == 1;
    }
};

class Solution {
public:
    vector<vector<string>> groupAnagrams(vector<string>& strs) {
        unordered_map<string, vector<string>> groups;
        for (const string& word : strs) {
            string key = word;
            sort(key.begin(), key.end());
            groups[key].push_back(word);
        }
        vector<vector<string>> answer;
        for (auto& [key, group] : groups) answer.push_back(move(group));
        return answer;
    }
};

class Solution {
public:
    vector<int> sortedSquares(vector<int>& nums) {
        vector<int> answer(nums.size());
        int left = 0, right = nums.size() - 1;
        for (int write = nums.size() - 1; write >= 0; --write) {
            if (abs(nums[left]) > abs(nums[right])) answer[write] = nums[left] * nums[left++];
            else answer[write] = nums[right] * nums[right--];
        }
        return answer;
    }
};

class Solution {
public:
    vector<int> twoSum(vector<int>& numbers, int target) {
        int left = 0, right = numbers.size() - 1;
        while (left < right) {
            int sum = numbers[left] + numbers[right];
            if (sum == target) return {left + 1, right + 1};
            if (sum < target) ++left; else --right;
        }
        return {};
    }
};

class Solution {
public:
    int maxArea(vector<int>& height) {
        int left = 0, right = height.size() - 1, best = 0;
        while (left < right) {
            best = max(best, min(height[left], height[right]) * (right - left));
            if (height[left] < height[right]) ++left; else --right;
        }
        return best;
    }
};

class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        vector<vector<int>> answer;
        for (int i = 0; i + 2 < nums.size(); ++i) {
            if (i && nums[i] == nums[i - 1]) continue;
            int left = i + 1, right = nums.size() - 1;
            while (left < right) {
                int sum = nums[i] + nums[left] + nums[right];
                if (sum < 0) ++left;
                else if (sum > 0) --right;
                else {
                    answer.push_back({nums[i], nums[left], nums[right]});
                    int a = nums[left], b = nums[right];
                    while (left < right && nums[left] == a) ++left;
                    while (left < right && nums[right] == b) --right;
                }
            }
        }
        return answer;
    }
};

class Solution {
public:
    bool isValid(string s) {
        stack<char> openings;
        unordered_map<char, char> match{{')','('},{']','['},{'}','{'}};
        for (char c : s) {
            if (!match.count(c)) openings.push(c);
            else {
                if (openings.empty() || openings.top() != match[c]) return false;
                openings.pop();
            }
        }
        return openings.empty();
    }
};

class Solution {
public:
    int calPoints(vector<string>& operations) {
        vector<int> scores;
        for (const string& op : operations) {
            if (op == "+") scores.push_back(scores.back() + scores[scores.size() - 2]);
            else if (op == "D") scores.push_back(2 * scores.back());
            else if (op == "C") scores.pop_back();
            else scores.push_back(stoi(op));
        }
        return accumulate(scores.begin(), scores.end(), 0);
    }
};

class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> greater;
        stack<int> pending;
        for (int value : nums2) {
            while (!pending.empty() && pending.top() < value) {
                greater[pending.top()] = value;
                pending.pop();
            }
            pending.push(value);
        }
        vector<int> answer;
        for (int value : nums1) answer.push_back(greater.count(value) ? greater[value] : -1);
        return answer;
    }
};

class MinStack {
    stack<pair<int, int>> values;
public:
    MinStack() {}
    void push(int val) {
        int minimum = values.empty() ? val : min(val, values.top().second);
        values.push({val, minimum});
    }
    void pop() { values.pop(); }
    int top() { return values.top().first; }
    int getMin() { return values.top().second; }
};

class StockSpanner {
    stack<pair<int, int>> prices;
public:
    StockSpanner() {}
    int next(int price) {
        int span = 1;
        while (!prices.empty() && prices.top().first <= price) {
            span += prices.top().second;
            prices.pop();
        }
        prices.push({price, span});
        return span;
    }
};

class Solution {
public:
    double findMaxAverage(vector<int>& nums, int k) {
        long long window = accumulate(nums.begin(), nums.begin() + k, 0LL), best = window;
        for (int right = k; right < nums.size(); ++right) {
            window += nums[right] - nums[right - k];
            best = max(best, window);
        }
        return static_cast<double>(best) / k;
    }
};

class Solution {
public:
    int maxVowels(string s, int k) {
        auto vowel = [](char c) { return string("aeiou").find(c) != string::npos; };
        int count = 0;
        for (int i = 0; i < k; ++i) count += vowel(s[i]);
        int best = count;
        for (int right = k; right < s.size(); ++right) {
            count += vowel(s[right]) - vowel(s[right - k]);
            best = max(best, count);
        }
        return best;
    }
};

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        array<int, 256> last; last.fill(-1);
        int left = 0, best = 0;
        for (int right = 0; right < s.size(); ++right) {
            left = max(left, last[(unsigned char)s[right]] + 1);
            last[(unsigned char)s[right]] = right;
            best = max(best, right - left + 1);
        }
        return best;
    }
};

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int left = 0, sum = 0, best = INT_MAX;
        for (int right = 0; right < nums.size(); ++right) {
            sum += nums[right];
            while (sum >= target) {
                best = min(best, right - left + 1);
                sum -= nums[left++];
            }
        }
        return best == INT_MAX ? 0 : best;
    }
};

class Solution {
public:
    int search(vector<int>& nums, int target) {
        int low = 0, high = nums.size() - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) return mid;
            if (nums[mid] < target) low = mid + 1; else high = mid - 1;
        }
        return -1;
    }
};

class Solution {
public:
    int searchInsert(vector<int>& nums, int target) {
        int low = 0, high = nums.size();
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] < target) low = mid + 1; else high = mid;
        }
        return low;
    }
};

class Solution {
public:
    int firstBadVersion(int n) {
        int low = 1, high = n;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (isBadVersion(mid)) high = mid; else low = mid + 1;
        }
        return low;
    }
};

class Solution {
public:
    int mySqrt(int x) {
        if (x < 2) return x;
        int low = 1, high = x / 2, answer = 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (mid <= x / mid) { answer = mid; low = mid + 1; }
            else high = mid - 1;
        }
        return answer;
    }
};

class Solution {
    int lower(vector<int>& nums, long long target) {
        int low = 0, high = nums.size();
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] < target) low = mid + 1; else high = mid;
        }
        return low;
    }
public:
    vector<int> searchRange(vector<int>& nums, int target) {
        int first = lower(nums, target);
        if (first == nums.size() || nums[first] != target) return {-1, -1};
        return {first, lower(nums, (long long)target + 1) - 1};
    }
};

class Solution {
public:
    int findMin(vector<int>& nums) {
        int low = 0, high = nums.size() - 1;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] > nums[high]) low = mid + 1; else high = mid;
        }
        return nums[low];
    }
};

class Solution {
public:
    int search(vector<int>& nums, int target) {
        int low = 0, high = nums.size() - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) return mid;
            if (nums[low] <= nums[mid]) {
                if (nums[low] <= target && target < nums[mid]) high = mid - 1;
                else low = mid + 1;
            } else {
                if (nums[mid] < target && target <= nums[high]) low = mid + 1;
                else high = mid - 1;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int minEatingSpeed(vector<int>& piles, int h) {
        int low = 1, high = *max_element(piles.begin(), piles.end());
        while (low < high) {
            int speed = low + (high - low) / 2;
            long long hours = 0;
            for (int pile : piles) hours += (pile + speed - 1LL) / speed;
            if (hours <= h) high = speed; else low = speed + 1;
        }
        return low;
    }
};

class Solution {
public:
    int fib(int n) {
        int previous = 0, current = 1;
        for (int i = 0; i < n; ++i) {
            int next = previous + current;
            previous = current;
            current = next;
        }
        return previous;
    }
};

class Solution {
public:
    bool isPowerOfThree(int n) {
        if (n <= 0) return false;
        while (n % 3 == 0) n /= 3;
        return n == 1;
    }
};

class Solution {
    double power(double x, long long n) {
        if (n == 0) return 1.0;
        double half = power(x, n / 2);
        return half * half * (n % 2 ? x : 1.0);
    }
public:
    double myPow(double x, int n) {
        long long exponent = n;
        return exponent < 0 ? 1.0 / power(x, -exponent) : power(x, exponent);
    }
};

class Solution {
public:
    ListNode* middleNode(ListNode* head) {
        ListNode *slow = head, *fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        return slow;
    }
};

class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        ListNode* previous = nullptr;
        while (head) {
            ListNode* next = head->next;
            head->next = previous;
            previous = head;
            head = next;
        }
        return previous;
    }
};

class Solution {
public:
    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
        ListNode dummy, *tail = &dummy;
        while (list1 && list2) {
            if (list1->val <= list2->val) { tail->next = list1; list1 = list1->next; }
            else { tail->next = list2; list2 = list2->next; }
            tail = tail->next;
        }
        tail->next = list1 ? list1 : list2;
        return dummy.next;
    }
};

class Solution {
public:
    bool hasCycle(ListNode* head) {
        ListNode *slow = head, *fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
            if (slow == fast) return true;
        }
        return false;
    }
};

class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        ListNode dummy(0, head), *slow = &dummy, *fast = &dummy;
        for (int i = 0; i <= n; ++i) fast = fast->next;
        while (fast) { slow = slow->next; fast = fast->next; }
        slow->next = slow->next->next;
        return dummy.next;
    }
};

class Solution {
public:
    int maxDepth(TreeNode* root) {
        if (!root) return 0;
        return 1 + max(maxDepth(root->left), maxDepth(root->right));
    }
};

class Solution {
public:
    bool isSameTree(TreeNode* p, TreeNode* q) {
        if (!p || !q) return p == q;
        return p->val == q->val && isSameTree(p->left, q->left) && isSameTree(p->right, q->right);
    }
};

class Solution {
public:
    TreeNode* invertTree(TreeNode* root) {
        if (!root) return nullptr;
        TreeNode* left = invertTree(root->left);
        root->left = invertTree(root->right);
        root->right = left;
        return root;
    }
};

class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> answer;
        stack<TreeNode*> pending;
        while (root || !pending.empty()) {
            while (root) { pending.push(root); root = root->left; }
            root = pending.top(); pending.pop();
            answer.push_back(root->val);
            root = root->right;
        }
        return answer;
    }
};

class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        if (!root) return {};
        vector<vector<int>> answer;
        queue<TreeNode*> pending; pending.push(root);
        while (!pending.empty()) {
            int count = pending.size();
            answer.push_back({});
            while (count--) {
                TreeNode* node = pending.front(); pending.pop();
                answer.back().push_back(node->val);
                if (node->left) pending.push(node->left);
                if (node->right) pending.push(node->right);
            }
        }
        return answer;
    }
};

class Solution {
    bool valid(TreeNode* node, long long low, long long high) {
        if (!node) return true;
        if (node->val <= low || node->val >= high) return false;
        return valid(node->left, low, node->val) && valid(node->right, node->val, high);
    }
public:
    bool isValidBST(TreeNode* root) {
        return valid(root, LLONG_MIN, LLONG_MAX);
    }
};
